<div class="brief-list"><?php foreach ($listing['items'] as $item): $result = $item->result; $status = $item->status($listing['staleBefore']); ?><article class="brief-list-item indexing-item"><div><div class="actions"><span class="indexing-badge"><?= $view->e(IndexingService::FILTERS[$status]) ?></span><?php if ($item->watched): ?><span class="indexing-badge">Weekly watch</span><?php endif; ?></div><h3 class="brief-url"><a href="<?= $view->e('/projects/' . $project->publicId . '/pages/details?url=' . rawurlencode($item->url)) ?>"><?= $view->e($item->url) ?></a></h3>
